const {
  withDangerousMod,
  withMainApplication,
  withAndroidManifest,
  AndroidConfig,
} = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

/**
 * Config plugin for the Android "Today's Schedule" home-screen widget. Like
 * withGucAuth, the `android/` folder is regenerated by `expo prebuild`, so this
 * recreates everything the widget needs:
 *
 *   1. The Kotlin sources (provider, list service, data store, RN bridge module).
 *   2. The layouts / drawables / colors / strings / widget-info resources.
 *   3. Registration of ScheduleWidgetPackage in MainApplication.kt.
 *   4. The <receiver> + <service> entries in AndroidManifest.xml.
 *
 * The canonical native sources live in ./schedulewidget and are the source of truth.
 */

const TEMPLATE_DIR = path.join(__dirname, 'schedulewidget');
const SOURCE_FILES = [
  'ScheduleWidgetData.kt',
  'ScheduleWidgetProvider.kt',
  'ScheduleWidgetService.kt',
  'ScheduleWidgetModule.kt',
  'ScheduleWidgetPackage.kt',
];

function getPackage(config) {
  const pkg = config.android && config.android.package;
  if (!pkg) {
    throw new Error('withScheduleWidget: expo.android.package must be set in app config.');
  }
  return pkg;
}

function copyDir(src, dest) {
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);
    if (entry.isDirectory()) copyDir(from, to);
    else fs.copyFileSync(from, to);
  }
}

// 1 + 2. Copy the Kotlin sources and Android resources into the generated project.
const withScheduleWidgetNativeFiles = (config) =>
  withDangerousMod(config, [
    'android',
    (cfg) => {
      const pkg = getPackage(cfg);
      const androidRoot = cfg.modRequest.platformProjectRoot; // .../android

      const javaDir = path.join(
        androidRoot,
        'app/src/main/java',
        ...`${pkg}.schedulewidget`.split('.')
      );
      fs.mkdirSync(javaDir, { recursive: true });

      for (const name of SOURCE_FILES) {
        const template = fs.readFileSync(path.join(TEMPLATE_DIR, name), 'utf8');
        // Templates use `com.anonymous.unilink` (package + R import); retarget it
        // to the app's real package so a package rename still works.
        const contents = template.replace(/com\.anonymous\.unilink/g, pkg);
        fs.writeFileSync(path.join(javaDir, name), contents);
      }

      copyDir(path.join(TEMPLATE_DIR, 'res'), path.join(androidRoot, 'app/src/main/res'));
      return cfg;
    },
  ]);

// 3. Register ScheduleWidgetPackage in MainApplication.kt.
const withScheduleWidgetMainApplication = (config) =>
  withMainApplication(config, (cfg) => {
    const pkg = getPackage(cfg);
    let src = cfg.modResults.contents;

    const importLine = `import ${pkg}.schedulewidget.ScheduleWidgetPackage`;
    if (!src.includes(importLine)) {
      src = src.replace(/(^package .*$)/m, `$1\n\n${importLine}`);
    }

    if (!src.includes('add(ScheduleWidgetPackage())')) {
      src = src.replace(
        /(PackageList\(this\)\.packages\.apply\s*\{)/,
        `$1\n              add(ScheduleWidgetPackage())`
      );
    }

    cfg.modResults.contents = src;
    return cfg;
  });

// 4. Declare the widget receiver, its list service and the exact-alarm permission.
const withScheduleWidgetManifest = (config) =>
  withAndroidManifest(config, (cfg) => {
    const pkg = getPackage(cfg);
    const manifest = cfg.modResults;
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(manifest);

    // Lets the widget flip to the next session on time (granted by default on
    // Android 12/13; on 14+ unless granted, Android may deliver it up to ~10 min late).
    AndroidConfig.Permissions.ensurePermission(manifest, 'android.permission.SCHEDULE_EXACT_ALARM');

    const receiverName = `${pkg}.schedulewidget.ScheduleWidgetProvider`;
    app.receiver = (app.receiver || []).filter((r) => r.$['android:name'] !== receiverName);
    app.receiver.push({
      $: {
        'android:name': receiverName,
        'android:exported': 'false',
        'android:label': '@string/schedule_widget_label',
      },
      'intent-filter': [
        {
          action: [
            { $: { 'android:name': 'android.appwidget.action.APPWIDGET_UPDATE' } },
            { $: { 'android:name': 'android.intent.action.TIME_SET' } },
            { $: { 'android:name': 'android.intent.action.TIMEZONE_CHANGED' } },
          ],
        },
      ],
      'meta-data': [
        {
          $: {
            'android:name': 'android.appwidget.provider',
            'android:resource': '@xml/schedule_widget_info',
          },
        },
      ],
    });

    const serviceName = `${pkg}.schedulewidget.ScheduleWidgetService`;
    app.service = (app.service || []).filter((s) => s.$['android:name'] !== serviceName);
    app.service.push({
      $: {
        'android:name': serviceName,
        'android:exported': 'false',
        'android:permission': 'android.permission.BIND_REMOTEVIEWS',
      },
    });

    return cfg;
  });

module.exports = function withScheduleWidget(config) {
  config = withScheduleWidgetNativeFiles(config);
  config = withScheduleWidgetMainApplication(config);
  config = withScheduleWidgetManifest(config);
  return config;
};
